// Copyright 2024 Apheleia
//
// Description:
// Apheleia Verification Library (AVL) Benchmark
//
// Bitwise constraints - and, or, xor, shift and bit select, and nothing else.
// No arithmetic, no sets, no implications.
//
// This file is compiled unchanged by both flavours of the benchmark. Clock and
// reset are generated by the cocotb testbench in ../cocotb/bitwise.py, which
// also runs the iteration loop, so the two flavours share an identical harness.
//
// Only the randomization itself differs, and it is the sole thing inside the
// `ifdef below.

`timescale 1ns/1ps

module bitwise_bench (
    input logic clk,
    input logic rst_n
);

    // Common to both flavours - lets the testbench confirm that both ran for
    // the same number of clock cycles.
    int unsigned cycles = 0;

    always @(posedge clk) begin
        if (!rst_n) begin
            cycles <= 0;
        end
        else begin
            cycles <= cycles + 1;
        end
    end

`ifdef BENCH_SV_RANDOMIZE
    // -----------------------------------------------------------------------
    // Randomization under test - SystemVerilog classes and constraints.
    // -----------------------------------------------------------------------

    class bitwise_item;

        rand bit [31:0] a;
        rand bit [31:0] b;
        rand bit [31:0] c;
        rand bit [31:0] d;

        // Masked equality - fixes the bottom byte, leaves the rest free.
        constraint c_a { (a & 32'h0000_00ff) == 32'h0000_005a; }

        // Or - forces the top half to all ones, leaves the bottom half free.
        constraint c_b { (b | 32'h0000_ffff) == 32'hffff_ffff; }

        // Xor against a pattern, masked to the top half.
        constraint c_c { ((c ^ 32'ha5a5_a5a5) & 32'hffff_0000) == 32'h5a5a_0000; }

        // Logical shift right, then masked equality, and a bit select.
        constraint c_d { ((d >> 8) & 32'h0000_00ff) == 32'h0000_003c;
                         d[31:28] == 4'b1010; }

    endclass : bitwise_item

    bitwise_item     item;
    bit              enable   = 1'b1;
    int unsigned     burst    = 1;
    longint unsigned checksum = 0;
    int unsigned     count    = 0;

    // Written only by the quality run, which is untimed - see +dump.
    int              dump_fd  = 0;
    string           dump_file;

    initial begin
        // Cleared for the baseline run, which measures the harness on its own.
        void'($value$plusargs("randomize=%d", enable));
        void'($value$plusargs("burst=%d", burst));

        if ($value$plusargs("dump=%s", dump_file)) begin
            dump_fd = $fopen(dump_file, "w");
            $fwrite(dump_fd, "a:32,b:32,c:32,d:32\n");
        end
    end

    always @(posedge clk) begin
        if (rst_n && enable) begin
            repeat (burst) begin
                // A fresh item per randomization, the way a testbench builds
                // a fresh sequence item per transaction, rather than one item
                // reused - which would let a solver amortize work across draws.
                item = new();

                if (item.randomize() == 0) begin
                    $fatal(1, "randomization failed on iteration %0d", count);
                end

                if ((item.a & 32'h0000_00ff) != 32'h0000_005a) begin
                    $fatal(1, "c_a violated : a=%08x", item.a);
                end
                if ((item.b | 32'h0000_ffff) != 32'hffff_ffff) begin
                    $fatal(1, "c_b violated : b=%08x", item.b);
                end
                if (((item.c ^ 32'ha5a5_a5a5) & 32'hffff_0000) != 32'h5a5a_0000) begin
                    $fatal(1, "c_c violated : c=%08x", item.c);
                end
                if ((((item.d >> 8) & 32'h0000_00ff) != 32'h0000_003c) ||
                    (item.d[31:28] != 4'b1010)) begin
                    $fatal(1, "c_d violated : d=%08x", item.d);
                end

                if (dump_fd != 0) begin
                    $fwrite(dump_fd, "%0d,%0d,%0d,%0d\n", item.a, item.b, item.c, item.d);
                end

                checksum += 64'(item.a) + 64'(item.b) + 64'(item.c) + 64'(item.d);
                count    += 1;
            end
        end
    end

    final begin
        if (dump_fd != 0) $fclose(dump_fd);
        $display("BENCH_RESULT flavour=sv iterations=%0d checksum=%0d", count, checksum);
    end
`endif

endmodule : bitwise_bench
